#else
  return texture2D(tex, uv);
#endif
}
#if USE_ALPHA_TEST
#endif
varying vec4 color;
varying vec2 uv0;
uniform sampler2D cc_spriteTexture;
   uniform vec4 sweepColor;
   uniform float sweepProgress;
   uniform float sweepWidth;
   uniform float sweepStrength;
   uniform float sweepSkew;
vec4 frag () {
  vec4 base = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0) * color;
