  float dist = abs(coord - pos);
  float t = max(0.0, 1.0 - dist / sweepWidth);
  float highlight = t * t * sweepStrength;
  vec3 rgb = base.rgb + sweepColor.rgb * highlight * base.a;
  return vec4(rgb, base.a);
}
void main() { gl_FragColor = frag(); }
